import java.util.*;
class Student {
    String name;
    int marks;
    Student(String n,int m){name=n;marks=m;}
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        ArrayList<Student> list = new ArrayList<>();
        for(int i=0;i<n;i++) {
            list.add(new Student(sc.next(), sc.nextInt()));
        }
