public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int capacity = sc.nextInt();
        int n = sc.nextInt();
        LinkedList<Integer> cache = new LinkedList<>();
        for(int i=0;i<n;i++) {
            int x = sc.nextInt();
            if(cache.contains(x)) {
                cache.remove((Integer)x);
            }
            else if(cache.size() == capacity) {
                cache.removeFirst();
            }
            cache.addLast(x);
        }
        for(int x : cache) {
            System.out.print(x + " ");
        }
    }
}

