        int n = sc.nextInt();
        int[] arr = new int[n];
        for(int i=0;i<n;i++) arr[i] = sc.nextInt();
        int k = sc.nextInt();
        LinkedHashMap<Integer,Integer> cache = new LinkedHashMap<>(16,0.75f,true);
        for(int x : arr) {
            cache.put(x,x);
            if(cache.size() > k) {
                int first = cache.keySet().iterator().next();
                cache.remove(first);
            }
        }
        for(int key : cache.keySet()) {
